-- ts-design-studio 1.0.0 – projekty, verze a záznam akcí (MySQL)
CREATE TABLE IF NOT EXISTS studio_projects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, source VARCHAR(10) NOT NULL, lead_ref VARCHAR(64) NOT NULL DEFAULT '', audit_ref VARCHAR(64) NOT NULL DEFAULT '', template VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', owner_uid INT NOT NULL DEFAULT 0, current_num INT NOT NULL DEFAULT 0, brief TEXT NOT NULL, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS studio_versions (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, num INT NOT NULL, parent_num INT NOT NULL DEFAULT 0, kind VARCHAR(10) NOT NULL, author_uid INT NOT NULL DEFAULT 0, author_kind VARCHAR(10) NOT NULL, message VARCHAR(500) NOT NULL DEFAULT '', files MEDIUMTEXT NOT NULL, content MEDIUMTEXT NOT NULL, tokens TEXT NOT NULL, checks MEDIUMTEXT NOT NULL, status VARCHAR(10) NOT NULL, created_at VARCHAR(19) NOT NULL, UNIQUE KEY studio_versions_num (project_id, num)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS studio_log (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, num INT NOT NULL DEFAULT 0, uid INT NOT NULL DEFAULT 0, action VARCHAR(30) NOT NULL, detail VARCHAR(500) NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL, INDEX studio_log_project (project_id, id)) DEFAULT CHARSET=utf8mb4;
